<script setup>
import {onBeforeUnmount,onMounted,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,csrf:String});const state=reactive({rows:[],roles:[],stats:{},pagination:{},filters:{search:'',role:'',status:''}});const loading=ref(true),error=ref('');let abort,timer;
async function load(url=location.href,push=false){abort?.abort();abort=new AbortController();loading.value=true;error.value='';try{const r=await fetch(url,{credentials:'same-origin',signal:abort.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}),d=await r.json();if(!r.ok)throw new Error(d.message||`Request failed (${r.status})`);state.rows=d.users||[];state.roles=d.roles||[];state.stats=d.stats||{};state.pagination=d.pagination||{};state.filters={search:'',role:'',status:'',...(d.filters||{})};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{loading.value=false}}
function filterUrl(){const u=new URL(props.indexUrl,location.origin);for(const[k,v]of Object.entries(state.filters))if(v)u.searchParams.set(k,v);return u.href}function apply(){load(filterUrl(),true)}function search(){clearTimeout(timer);timer=setTimeout(apply,350)}function page(l){if(l.url)load(l.url,true)}
async function updateStatus(user,status){if(user.is_current)return;const body=new FormData();body.append('_method','PATCH');body.append('status',status);try{const r=await fetch(user.status_url,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body});const d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to update status');user.status=status}catch(e){error.value=e.message}}
async function remove(user){let yes=true;if(window.Swal){const x=await window.Swal.fire({title:'Delete user?',text:`Delete ${user.name}? Existing orders prevent deletion.`,icon:'warning',showCancelButton:true,confirmButtonText:'Delete'});yes=x.isConfirmed}else yes=confirm(`Delete ${user.name}?`);if(!yes)return;const body=new FormData();body.append('_method','DELETE');try{const r=await fetch(user.delete_url,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body});const d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to delete user');await load(location.href)}catch(e){error.value=e.message}}
function pop(){load(location.href)}onMounted(()=>{const p=new URLSearchParams(location.search);state.filters={search:p.get('search')||'',role:p.get('role')||'',status:p.get('status')||''};if(props.mode==='index')load(props.indexUrl+location.search);window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{clearTimeout(timer);abort?.abort();window.removeEventListener('popstate',pop)});
</script>
<template><div class="users-hero mb-4"><div class="users-hero-content"><span class="hero-badge"><i class="bi bi-shield-check"></i> SecondBook Community</span><h1>People behind every page.</h1><p>Keep your reader community organised, verified and ready to grow.</p></div><div class="users-hero-mark"><i class="bi bi-people-fill"></i></div></div><div class="row g-4 mb-4"><div class="col-12 col-sm-6 col-xl-3"><div class="user-stat-card stat-blue"><div><span>Total users</span><strong>{{ Number(state.stats.total||0).toLocaleString() }}</strong></div><i class="bi bi-people"></i></div></div><div class="col-12 col-sm-6 col-xl-3"><div class="user-stat-card stat-green"><div><span>Active users</span><strong>{{ Number(state.stats.active||0).toLocaleString() }}</strong></div><i class="bi bi-person-check"></i></div></div><div class="col-12 col-sm-6 col-xl-3"><div class="user-stat-card stat-orange"><div><span>Inactive / banned</span><strong>{{ Number(state.stats.inactive||0).toLocaleString() }}</strong></div><i class="bi bi-person-slash"></i></div></div><div class="col-12 col-sm-6 col-xl-3"><div class="user-stat-card stat-purple"><div><span>Admin users</span><strong>{{ Number(state.stats.admins||0).toLocaleString() }}</strong></div><i class="bi bi-shield-lock"></i></div></div></div><div class="dashboard-panel users-panel"><div class="panel-header users-panel-header"><div class="users-heading-content"><span class="eyebrow">Community directory</span><h5>All users</h5><p>Search and review every account in your marketplace.</p></div><div class="users-header-action"><a :href="createUrl" class="btn btn-primary users-add-btn"><i class="bi bi-person-plus"></i><span>Add user</span></a></div></div><form class="user-filters" @submit.prevent="apply"><input v-model="state.filters.search" class="form-control" placeholder="Search name, email, phone..." @input="search"><select v-model="state.filters.role" class="form-select"><option value="">All roles</option><option v-for="r in state.roles" :key="r.name" :value="r.name">{{ r.display_name }}</option></select><select v-model="state.filters.status" class="form-select"><option value="">All statuses</option><option v-for="s in ['active','inactive','banned']" :key="s">{{ s }}</option></select><button class="btn btn-primary"><i class="bi bi-funnel"></i> Filter</button><button v-if="Object.values(state.filters).some(Boolean)" type="button" class="btn btn-light" @click="state.filters={search:'',role:'',status:''};apply()">Clear</button></form><div v-if="error" class="alert alert-danger m-3">{{ error }} <button class="btn btn-light btn-sm" @click="load()">Retry</button></div><div class="users-table-wrap"><table class="table users-table align-middle"><thead><tr><th>User</th><th class="d-none d-md-table-cell">Email</th><th class="d-none d-lg-table-cell">Phone</th><th>Role</th><th>Status</th><th class="d-none d-xl-table-cell">Registered</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="text-center py-4">Loading users…</td></tr><tr v-for="u in state.rows" v-else :key="u.id"><td><div class="member-cell"><img v-if="u.photo_url" :src="u.photo_url" class="member-avatar member-avatar-image" :alt="u.name"><span v-else class="member-avatar">{{ (u.name||'?').slice(0,1).toUpperCase() }}</span><div><strong>{{ u.name }}</strong><small class="d-block">@{{ u.username }}</small></div></div></td><td class="d-none d-md-table-cell"><span class="user-email">{{ u.email }}</span><small class="verification-note"><i class="bi" :class="u.email_verified_at?'bi-check-circle text-success':'bi-clock text-warning'"></i> {{ u.email_verified_at?'Verified':'Unverified' }}</small></td><td class="d-none d-lg-table-cell"><span class="user-phone">{{ u.phone||'—' }}</span></td><td><span class="role-pill" :class="u.role === 'admin' || u.role === 'super-admin' ? 'role-admin' : 'role-member'"><i class="bi" :class="u.role === 'super-admin' ? 'bi-shield-fill-check' : (u.role === 'admin' ? 'bi-stars' : 'bi-person')"></i>{{ u.role_display }}</span></td><td><span class="status-pill" :class="`status-${u.status}`">{{ u.status }}</span></td><td class="d-none d-xl-table-cell">{{ u.registered_at }}</td><td><div class="user-actions"><a :href="u.show_url" class="btn btn-light btn-sm border user-action-btn" title="View"><i class="bi bi-eye"></i></a><a :href="u.edit_url" class="btn btn-warning btn-sm user-action-btn" title="Edit"><i class="bi bi-pencil"></i></a><button v-if="!u.is_current" class="btn btn-light btn-sm border user-action-btn" :title="u.status==='active'?'Deactivate':'Activate'" @click="updateStatus(u,u.status==='active'?'inactive':'active')"><i class="bi" :class="u.status==='active'?'bi-pause-circle':'bi-play-circle'"></i></button><button v-if="!u.is_current && u.status!=='banned'" class="btn btn-light btn-sm border text-danger user-action-btn" title="Ban" @click="updateStatus(u,'banned')"><i class="bi bi-slash-circle"></i></button><button v-if="!u.is_current" class="btn btn-danger btn-sm user-action-btn" title="Delete" @click="remove(u)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!loading&&!state.rows.length"><td colspan="7" class="text-center py-4">No users found.</td></tr></tbody></table></div><div v-if="state.pagination.total>10" class="users-pagination"><span>Showing {{ state.pagination.first_item }} to {{ state.pagination.last_item }} of {{ state.pagination.total }} users</span><nav><button v-for="(l,i) in state.pagination.links" :key="i" class="page-link" :class="{active:l.active,disabled:!l.url}" :disabled="!l.url" @click="page(l)" v-html="l.label.replace('&laquo;','‹').replace('&raquo;','›')"></button></nav></div></div></template>
